type Op = Record<string, unknown>

const ops: Op[] = []

function create(id: string, type: string, x: number, y: number, w: number, h: number, color: string, extra: Record<string, unknown> = {}) {
  ops.push({ type: 'create', shape: { id, type, x, y, w, h, color, ...extra } })
}

function path(id: string, points: Array<{ x: number; y: number }>, color: string, strokeWidth = 4, brush = 'pencil') {
  const xs = points.map(p => p.x)
  const ys = points.map(p => p.y)
  const x = Math.min(...xs)
  const y = Math.min(...ys)
  let w = Math.max(...xs) - x
  let h = Math.max(...ys) - y
  if (w < 1) w = 1
  if (h < 1) h = 1
  create(id, 'path', x, y, w, h, color, {
    brush,
    strokeWidth,
    points: points.map(p => ({ x: p.x - x, y: p.y - y })),
  })
}

function text(id: string, x: number, y: number, w: number, h: number, value: string, color: string, fontSize: number, fontWeight = 400) {
  create(id, 'text', x, y, w, h, color, { text: value, font: 'sans', fontSize, fontWeight })
}

function arrow(id: string, x1: number, y1: number, x2: number, y2: number, color: string, size = 12, strokeWidth = 4) {
  const dx = x2 - x1
  const dy = y2 - y1
  const length = Math.hypot(dx, dy)
  const ux = dx / length
  const uy = dy / length
  const px = -uy
  const py = ux
  path(`${id}-shaft`, [
    { x: x1, y: y1 },
    { x: x2 - ux * size * 0.7, y: y2 - uy * size * 0.7 },
  ], color, strokeWidth)
  path(`${id}-head`, [
    { x: x2 - ux * size + px * size * 0.55, y: y2 - uy * size + py * size * 0.55 },
    { x: x2, y: y2 },
    { x: x2 - ux * size - px * size * 0.55, y: y2 - uy * size - py * size * 0.55 },
  ], color, strokeWidth)
}

